import re,json,sys,collections
S="/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad"
rows=[json.loads(l) for l in open(S+"/calls.jsonl")]
by=collections.defaultdict(list)
for r in rows: by[r[0]].append(r)
def kinds(c):
    k=[]
    if re.search(r'ant\s+(-\S+\s+)*compileAll',c): k.append('compileAll')
    if re.search(r'ant\s+(-\S+\s+)*(testFast|testSystem)',c): k.append('SUITE')
    if re.search(r'(CompilerJUTest|LibraryJUTest|OtherCompilerJUTest)\b',c) and 'harness-one' not in c: k.append('JUNITCLASS')
    if re.search(r'fortress compile\S*\s+\S*(AnyType|CompilerBuiltin|CompilerLibrary|CompilerAlgebra|CompilerSystem)\.fss',c) or re.search(r'for c in .*AnyType',c): k.append('lib')
    if 'checker-count/run.sh' in c: k.append('checker')
    if 'distance/run.sh' in c: k.append('distance')
    if 'run-subset' in c or 'run-ladder' in c: k.append('ladder')
    if 'mg-run.sh' in c: k.append('microgpt')
    if 'harness-one' in c or 'junit.sh' in c or 'Shell junit' in c or 'fortress junit' in c or 'SystemJUTest' in c: k.append('harness')
    return k
def runs(cmd):
    # returns list of (logpath, payload) for run_bg launches, else [(None, cmd)]
    out=[]
    for m in re.finditer(r'run_bg\s+(\S+)\s+"(.*?)(?<!\\)"',cmd):
        out.append((m.group(1),m.group(2)))
    return out
for lab in sys.argv[1:]:
    rs=by[lab]; msgs=[]
    print('=====',lab)
    for idx,(l,i,t,dt,rlen,ti,tn,mid,cmd,res) in enumerate(rs):
        if cmd.startswith('Edit ') or cmd.startswith('Write '):
            m=re.search(r'"file_path": "([^"]+)"',cmd); fp=m.group(1) if m else ''
            if re.search(r'(ProjectFortress/(src|LibraryBuiltin)|/Library/)',fp):
                print(f"{i:>4} {t} EDIT {fp.split('/')[-1]}")
            continue
        g=re.findall(r'git (?:-C \S+ )?(commit|checkout|reset --hard|stash|cherry-pick|merge|apply|switch)[^;&|]{0,60}',cmd)
        launched=runs(cmd)
        if launched:
            for lp,pl in launched:
                k=kinds(pl)
                if not k: continue
                base=lp.split('/')[-1]
                end=None; tok=int(ti)+int(tn); polls=0
                for (l2,i2,t2,dt2,rl2,ti2,tn2,mid2,c2,r2) in rs[idx+1:]:
                    if base in c2:
                        polls+=1; tok+=int(ti2)+int(tn2)
                        if 'EXIT=' in r2: end=(t2,dt2,r2); break
                if end:
                    h,mn,s=map(int,end[0].split(':')); h0,m0,s0=map(int,t.split(':'))
                    wall=(h*3600+mn*60+s+int(end[1]))-(h0*3600+m0*60+s0)
                    rr=' '.join(sorted(set(re.findall(r'(BUILD \w+|Total time: [^\\]*?seconds?|EXIT=\d+|#total\s+\d+|OK \(\d+ tests?\)|Failures: \d+)',end[2]))))
                else: wall='?'; rr=''
                print(f"{i:>4} {t} BG {','.join(k):<14} wall~{wall}s polls={polls} w={tok} {base} :: {pl[:150]} || {rr[:120]}")
        else:
            k=kinds(cmd)
            # skip pure reads of scripts
            if k and not re.search(r'^(cat|sed|head|grep|ls|tail|wc)\b',cmd.split('&&')[-1].strip()) and int(dt)>=5:
                rr=' '.join(sorted(set(re.findall(r'(BUILD \w+|Total time: [^\\]*?seconds?|EXIT=\d+|#total\s+\d+|OK \(\d+ tests?\)|Failures: \d+)',res))))
                print(f"{i:>4} {t} FG {','.join(k):<14} {dt}s w={int(ti)+int(tn)} :: {cmd[:170]} || {rr[:120]}")
        if g and any(x in ('commit','checkout','reset --hard','cherry-pick','merge','apply','stash','switch') for x in g):
            gg=[x for x in re.findall(r'git (?:-C \S+ )?((?:commit|checkout|reset --hard|cherry-pick|merge|apply|stash|switch)[^;&|]{0,50})',cmd) if 'global.map' not in x]
            if gg:
                hs=re.findall(r'\[[^\]]*? ([0-9a-f]{7,9})\]|HEAD is now at ([0-9a-f]{7,9})',res)
                print(f"{i:>4} {t} GIT {' / '.join(gg)[:140]} -> {hs[:2]}")
EOF
