private static void removeFiles(File file) throws IOException {
    if (file.exists() && file.isDirectory()) {
        for (File f : file.listFiles()) {
            removeFiles(f);
        }
    }
    else if (file.exists() && ! file.isDirectory()) {
        if (! file.delete())
            throw new IOException();
    }

}

